/* From Uiverse.io by alexruix - Tags: input */
/* From uiverse.io by @alexruix */
.__UIV_SCOPE__ .input {
 line-height: 28px;
 border: 2px solid transparent;
 border-bottom-color: #777;
 padding: .2rem 0;
 outline: none;
 background-color: transparent;
 color: #0d0c22;
 transition: .3s cubic-bezier(0.645, 0.045, 0.355, 1);
}

.__UIV_SCOPE__ .input:focus, .__UIV_SCOPE__ input:hover {
 outline: none;
 padding: .2rem 1rem;
 border-radius: 1rem;
 border-color: #7a9cc6;
}

.__UIV_SCOPE__ .input::placeholder {
 color: #777;
}

.__UIV_SCOPE__ .input:focus::placeholder {
 opacity: 0;
 transition: opacity .3s;
}
